// determineConfig will figure out which file to use for Flipt configuration.
func determineConfig(configFile string) (string, bool) {
	if configFile != "" {
		return configFile, true
	}

	_, err := os.Stat(userConfigFile)
	if err == nil {
		return userConfigFile, true
	}

	if !errors.Is(err, fs.ErrNotExist) {
		defaultLogger.Warn("unexpected error checking configuration file", zap.String("config_file", userConfigFile), zap.Error(err))
	}

	return defaultConfigFile, defaultConfigFile != ""
}

func buildConfig() (*zap.Logger, *config.Config, error) {
	path, found := determineConfig(providedConfigFile)

	// read in config if it exists
	// otherwise, use defaults
	res, err := config.Load(path)
	if err != nil {
		return nil, nil, fmt.Errorf("loading configuration %w", err)
	}

	if !found {
		defaultLogger.Info("no configuration file found, using defaults")
	}

package cmd

import (
	"context"
	"errors"
	"sync"
	"testing"

	"github.com/stretchr/testify/assert"
	"go.flipt.io/flipt/internal/config"
)

func TestGetTraceExporter(t *testing.T) {
	tests := []struct {
		name    string
		cfg     *config.Config
		wantErr error
	}{
		{
			name: "Jaeger",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingJaeger,
					Jaeger: config.JaegerTracingConfig{
						Host: "localhost",
						Port: 6831,
					},
				},
			},
		},
		{
			name: "Zipkin",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingZipkin,
					Zipkin: config.ZipkinTracingConfig{
						Endpoint: "http://localhost:9411/api/v2/spans",
					},
				},
			},
		},
		{
			name: "OTLP HTTP",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "http://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP HTTPS",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "https://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP GRPC",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "grpc://localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "OTLP default",
			cfg: &config.Config{
				Tracing: config.TracingConfig{
					Exporter: config.TracingOTLP,
					OTLP: config.OTLPTracingConfig{
						Endpoint: "localhost:4317",
						Headers:  map[string]string{"key": "value"},
					},
				},
			},
		},
		{
			name: "Unsupported Exporter",
			cfg: &config.Config{
				Tracing: config.TracingConfig{},
			},
			wantErr: errors.New("unsupported tracing exporter: "),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			traceExpOnce = sync.Once{}
			exp, expFunc, err := getTraceExporter(context.Background(), tt.cfg)
			if tt.wantErr != nil {
				assert.EqualError(t, err, tt.wantErr.Error())
				return
			}
			assert.NoError(t, err)
			assert.NotNil(t, exp)
			assert.NotNil(t, expFunc)
		})
	}
}
package cmd

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/go-chi/chi/v5"
	"github.com/stretchr/testify/assert"
)

const (
	tsoHeader = "trailing-slash-on"
)

func TestTrailingSlashMiddleware(t *testing.T) {
	r := chi.NewRouter()

	r.Use(func(h http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			tso := r.Header.Get(tsoHeader)
			if tso != "" {
				tsh := removeTrailingSlash(h)

				tsh.ServeHTTP(w, r)
				return
			}

			h.ServeHTTP(w, r)
		})
	})
	r.Get("/hello", func(w http.ResponseWriter, r *http.Request) {
	})

	s := httptest.NewServer(r)

	defer s.Close()

	// Request with the middleware on.
	req, err := http.NewRequestWithContext(context.TODO(), http.MethodGet, fmt.Sprintf("%s/hello/", s.URL), nil)
	assert.NoError(t, err)
	req.Header.Set(tsoHeader, "on")

	res, err := http.DefaultClient.Do(req)
	assert.NoError(t, err)

	assert.Equal(t, http.StatusOK, res.StatusCode)
	res.Body.Close()

	// Request with the middleware off.
	req, err = http.NewRequestWithContext(context.TODO(), http.MethodGet, fmt.Sprintf("%s/hello/", s.URL), nil)
	assert.NoError(t, err)

	res, err = http.DefaultClient.Do(req)
	assert.NoError(t, err)

	assert.Equal(t, http.StatusNotFound, res.StatusCode)
	res.Body.Close()
}
